//! Managed block inside AGENTS.md — the cross-agent instruction file.

use crate::config::Config;
use crate::report::NO_BYPASS;
use crate::rules::RuleInfo;
use std::fmt::Write;

const BEGIN_PREFIX: &str = "<!-- larpcop:begin";
const BEGIN: &str =
    "<!-- larpcop:begin — generated by `larpcop sync`; edits inside this block are overwritten -->";
const END: &str = "<!-- larpcop:end -->";

pub fn render(cfg: &Config, rules: &[RuleInfo]) -> String {
    let mut s = String::from("## Coding rules (enforced)\n\n");
    s.push_str(
        "Every rule below is checked mechanically by `larpcop`. Code that breaks an `error` rule is \
rejected by the pre-commit hook and by CI, no matter which agent or human wrote it.\n\n",
    );
    s.push_str("Workflow:\n\n");
    s.push_str("1. Follow the guidelines and rules below while writing code. Before editing a file, \
see the rules that apply to it: `rules_for` when the `larpcop` MCP server is available, \
`larpcop rules --for <file>` otherwise; `check_content` / `larpcop check <file>` before writing it.\n");
    s.push_str(
        "2. Before finishing a task, run `larpcop check --changed` and fix every violation.\n",
    );
    let _ = write!(s, "3. {NO_BYPASS}\n\n");
    if !cfg.guidelines.is_empty() {
        s.push_str("### Guidelines\n\n");
        for g in &cfg.guidelines {
            s.push_str(g.trim());
            s.push_str("\n\n");
        }
    }
    s.push_str("### Rules\n\n| Rule | Level | Applies to | Requirement |\n|---|---|---|---|\n");
    for r in rules {
        let requirement = match &r.note {
            Some(note) => format!("{} {}", r.message, note),
            None => r.message.clone(),
        };
        let _ = writeln!(
            s,
            "| `{}` | {} | {} | {} |",
            r.id,
            r.level.as_str(),
            cell(&r.scope),
            cell(&requirement)
        );
    }
    let _ = write!(
        s,
        "\nStandards applied (in order): {}\n",
        cfg.sources.join(" → ")
    );
    s
}

fn cell(text: &str) -> String {
    text.split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
        .replace('|', "\\|")
}

/// Replaces the managed block, or appends it; everything else is kept as is.
pub fn upsert(current: Option<&str>, block: &str) -> String {
    let wrapped = format!("{BEGIN}\n{block}{END}\n");
    let Some(cur) = current else {
        return format!("# AGENTS.md\n\n{wrapped}");
    };
    if let (Some(b), Some(e)) = (cur.find(BEGIN_PREFIX), cur.find(END))
        && b < e
    {
        let after = cur[e + END.len()..].trim_start_matches('\n');
        let sep = if after.is_empty() { "" } else { "\n" };
        return format!("{}{wrapped}{sep}{after}", &cur[..b]);
    }
    format!("{}\n\n{wrapped}", cur.trim_end())
}
